// The translations used by the JIRA administration.
define('jira-config-sheet-translation-keys', {
  prefix: 'jira.config.',
  keys: [
    'add.title',
    'edit.title',
    'error',
    'error.authSettings',
    'error.authLoad',
    'error.idRequired',
    'error.urlInvalid',
    'deploymentType.unavailable',
    'authType.unavailable',
    'saved',
    'deleted',
    'delete.confirm'
  ]
});

require(['jquery', 'xwiki-l10n!jira-config-sheet-translation-keys', 'bootstrap'], function ($, l10n) {
  const config = $('#jiraConfig');
  if (!config.length) {
    return;
  }
  // The pages displaying and saving the settings of each authentication type, by authentication type.
  const authDisplayerURLs = JSON.parse(config.attr('data-auth-displayer-urls') || '{}');
  const serviceURL = config.attr('data-service-url');
  const formToken = config.attr('data-form-token');

  const modal = $('#jiraInstanceModal');
  const form = modal.find('form.jira-instance-form');
  const fields = form.find('fieldset.jira-instance-fields');
  const authConfiguration = form.find('.jira-auth-configuration');
  const deleteModal = $('#jiraInstanceDeleteModal');

  // The instance being edited: its object number and the ID it has in the configuration (empty for a new instance).
  let currentInstance = {number: '', id: ''};
  // The ID the authentication settings are stored under, when the instance was renamed but its authentication settings
  // couldn't be saved: they have to be renamed when saving again. Null otherwise.
  let pendingPreviousId = null;
  // Ignore the responses of the previous requests when the authentication settings are reloaded several times.
  let authConfigurationRequest = 0;
  // Whether the settings of the selected authentication type are displayed: the instance can't be saved before, since
  // the settings sent would be missing or belong to another authentication type.
  let authConfigurationLoaded = false;
  // Whether the instance is being saved: the form can't be changed or closed meanwhile.
  let saving = false;
  // The fields are only marked as invalid once the form has been submitted, then while they are changed.
  let submitted = false;

  function getField(name) {
    return form.find(`[name="${name}"]`).first();
  }

  function getDeploymentType() {
    // The deployment type isn't displayed when no extension contributes deployment types.
    const deploymentType = getField('deploymentType');
    return deploymentType.length ? deploymentType.val() || '' : undefined;
  }

  function getAuthenticationType() {
    return getField('authenticationType').val() || 'noAuth';
  }

  // Get the translation with the given instance ID as parameter. The parameter is inserted as a String.replace
  // replacement: its "$" are doubled so that the ID is displayed as is, without interpreting $&, $1, etc.
  function formatMessage(key, id) {
    return l10n.get(key, String(id).split('$').join('$$'));
  }

  // The notification text is plain text since XWiki 17.10.9 / 18.4.0RC1, which added Notification.textFormat, and HTML
  // before.
  function notify(message, type) {
    const text = typeof XWiki.widgets.Notification.textFormat === 'function' ? message : message.escapeHTML();
    new XWiki.widgets.Notification(text, type);
  }

  function updateState() {
    fields.prop('disabled', saving);
    modal.find('button').prop('disabled', saving);
    modal.find('button[type="submit"]').prop('disabled', saving || !authConfigurationLoaded);
  }

  // Select the given value, adding an option for it when it isn't available anymore (e.g. the extension providing it
  // was uninstalled), so that it isn't changed silently.
  function selectValue(select, value, unavailableLabel) {
    if (!select.length) {
      return;
    }
    select.find('option.jira-unavailable').remove();
    const exists = select.find('option').filter(function () {
      return this.value === value;
    }).length > 0;
    if (!exists) {
      $('<option class="jira-unavailable"></option>').val(value).text(unavailableLabel).appendTo(select);
    }
    select.val(value);
  }

  function showError(message) {
    form.find('.jira-instance-error').text(message).prop('hidden', !message);
  }

  /**
   * Load the settings of the selected authentication type, from the page of this authentication type. The values
   * already typed are kept when the same authentication type is reloaded (e.g. when the deployment type changes).
   */
  async function loadAuthConfiguration() {
    const requestNumber = ++authConfigurationRequest;
    const authType = getAuthenticationType();
    const url = authDisplayerURLs[authType];
    const previousValues = authConfiguration.attr('data-auth-type') === authType
      ? authConfiguration.find(':input[name]').serializeArray() : [];
    authConfigurationLoaded = false;
    updateState();
    let html = '';
    if (url) {
      const parameters = {id: currentInstance.id, authType, deploymentType: getDeploymentType() || ''};
      try {
        const response = await fetch(`${url}?${new URLSearchParams(parameters)}`);
        if (!response.ok) {
          throw new Error(`Failed to load the authentication settings: ${response.status}`);
        }
        html = await response.text();
      } catch (e) {
        console.error(e);
        if (requestNumber === authConfigurationRequest) {
          // Don't keep the settings of another authentication type: the instance can't be saved until they're loaded.
          authConfiguration.empty().removeAttr('data-auth-type');
          showError(l10n.get('error.authLoad'));
        }
        return;
      }
    }
    if (requestNumber !== authConfigurationRequest) {
      return;
    }
    authConfiguration.html(html).attr('data-auth-type', authType);
    previousValues.forEach(field => {
      authConfiguration.find(':input[name]').filter(function () {
        return this.name === field.name && this.type !== 'checkbox' && this.type !== 'radio';
      }).val(field.value);
    });
    authConfigurationLoaded = true;
    updateState();
  }

  function openModal(instance) {
    if (saving) {
      return;
    }
    currentInstance = {number: instance.number || '', id: instance.id || ''};
    pendingPreviousId = null;
    form[0].reset();
    submitted = false;
    showError('');
    form.find('.has-error').removeClass('has-error');
    form.find('[aria-invalid]').removeAttr('aria-invalid');
    modal.find('.modal-title').text(l10n.get(currentInstance.number !== '' ? 'edit.title' : 'add.title'));
    getField('number').val(currentInstance.number);
    getField('id').val(currentInstance.id);
    getField('url').val(instance.url || '');
    selectValue(getField('deploymentType'), instance.deploymentType || '',
      l10n.get('deploymentType.unavailable'));
    selectValue(getField('authenticationType'), instance.authenticationType || 'noAuth',
      l10n.get('authType.unavailable'));
    authConfiguration.empty().removeAttr('data-auth-type');
    loadAuthConfiguration();
    modal.modal('show');
  }

  function getInstance(link) {
    // Read the attributes as strings, without any type conversion.
    return {
      number: link.attr('data-number'),
      id: link.attr('data-id'),
      url: link.attr('data-url'),
      deploymentType: link.attr('data-deployment-type'),
      authenticationType: link.attr('data-authentication-type')
    };
  }

  function refreshInstances() {
    const liveData = $('#jiraInstances').data('liveData');
    if (liveData) {
      liveData.updateEntries();
    } else {
      window.location.reload();
    }
  }

  function post(url, data) {
    return $.ajax({url, method: 'POST', data: $.param(Object.assign({form_token: formToken}, data), true)});
  }

  function getErrorMessage(xhr) {
    return xhr && xhr.responseJSON && xhr.responseJSON.error || l10n.get('error');
  }

  // Save the settings of the selected authentication type, and remove the settings of the instance from the other
  // authentication types. The values are the ones of the form when it was submitted.
  function saveAuthConfiguration(values) {
    const requests = [];
    Object.entries(authDisplayerURLs).forEach(([type, url]) => {
      if (type === values.authenticationType) {
        const data = {action: 'saveInstance', id: values.id, previousId: values.previousAuthId, url: values.url};
        if (values.deploymentType !== undefined) {
          data.deploymentType = values.deploymentType;
        }
        values.authFields.forEach(field => {
          if (!(field.name in data)) {
            data[field.name] = field.value;
          }
        });
        requests.push(post(url, data));
      } else {
        new Set([values.id, values.previousAuthId]).forEach(id => {
          if (id) {
            requests.push(post(url, {action: 'deleteInstance', id}));
          }
        });
      }
    });
    return Promise.all(requests);
  }

  function markInvalid(field, invalid) {
    field.attr('aria-invalid', invalid ? 'true' : null).closest('dd').prev('dt').addBack()
      .toggleClass('has-error', invalid);
  }

  function validate() {
    const id = getField('id');
    const url = getField('url');
    const idValid = id.val().trim() !== '';
    const urlValid = /^https?:\/\/\S/i.test(url.val().trim());
    markInvalid(id, !idValid);
    markInvalid(url, !urlValid);
    showError(!idValid ? l10n.get('error.idRequired') : (!urlValid ? l10n.get('error.urlInvalid') : ''));
    return idValid && urlValid;
  }

  async function save() {
    if (saving || !authConfigurationLoaded) {
      return;
    }
    submitted = true;
    if (!validate()) {
      return;
    }
    // Read the form once: it can't be changed while saving, but the requests must not depend on it anyway.
    const values = {
      number: currentInstance.number,
      // The ID the instance has in the configuration, checked by the service so that another instance isn't
      // overwritten if this one was deleted or changed in the meantime.
      currentId: currentInstance.id,
      // The ID the authentication settings are stored under.
      previousAuthId: pendingPreviousId !== null ? pendingPreviousId : currentInstance.id,
      id: getField('id').val().trim(),
      url: getField('url').val().trim(),
      deploymentType: getDeploymentType(),
      authenticationType: getAuthenticationType(),
      authFields: authConfiguration.find(':input[name]').serializeArray()
    };
    saving = true;
    updateState();
    try {
      const data = {
        action: 'save',
        number: values.number,
        previousId: values.currentId,
        id: values.id,
        url: values.url,
        authenticationType: values.authenticationType
      };
      if (values.deploymentType !== undefined) {
        data.deploymentType = values.deploymentType;
      }
      let result;
      try {
        result = await post(serviceURL, data);
      } catch (xhr) {
        showError(getErrorMessage(xhr));
        if (xhr && (xhr.status === 404 || xhr.status === 409)) {
          refreshInstances();
        }
        return;
      }
      if (!result || result.number === undefined) {
        showError(l10n.get('error'));
        return;
      }
      // The instance is saved: it's edited from now on, and its authentication settings are still stored under the
      // previous ID until they're saved.
      currentInstance = {number: String(result.number), id: result.id};
      pendingPreviousId = values.previousAuthId;
      getField('number').val(currentInstance.number);
      modal.find('.modal-title').text(l10n.get('edit.title'));
      try {
        await saveAuthConfiguration(values);
      } catch (xhr) {
        console.error(xhr);
        showError(l10n.get('error.authSettings'));
        refreshInstances();
        return;
      }
      pendingPreviousId = null;
      saving = false;
      modal.modal('hide');
      refreshInstances();
      notify(formatMessage('saved', values.id), 'done');
    } finally {
      saving = false;
      updateState();
    }
  }

  async function deleteInstance(instance) {
    const buttons = deleteModal.find('button').prop('disabled', true);
    try {
      await post(serviceURL, {action: 'delete', number: instance.number, id: instance.id});
      if (instance.id) {
        await Promise.all(Object.values(authDisplayerURLs).map(url =>
          post(url, {action: 'deleteInstance', id: instance.id})));
      }
      deleteModal.modal('hide');
      notify(formatMessage('deleted', instance.id), 'done');
    } catch (xhr) {
      notify(getErrorMessage(xhr), 'error');
    } finally {
      buttons.prop('disabled', false);
      refreshInstances();
    }
  }

  config.find('.jira-instance-add').on('click', () => openModal({}));

  // The edit and delete links are in the Live Data, which is (re)loaded asynchronously.
  $(document).on('click', '#jiraInstances a.jira-instance-edit', function (event) {
    event.preventDefault();
    openModal(getInstance($(this)));
  });

  $(document).on('click', '#jiraInstances a.jira-instance-delete', function (event) {
    event.preventDefault();
    const instance = getInstance($(this));
    deleteModal.data('instance', instance);
    deleteModal.find('.jira-instance-delete-message').text(formatMessage('delete.confirm', instance.id));
    deleteModal.modal('show');
  });

  deleteModal.find('.jira-instance-delete-confirm').on('click', () => deleteInstance(deleteModal.data('instance')));

  // The settings depend on the authentication type and their labels can depend on the deployment type.
  form.on('change', 'select[name="authenticationType"], select[name="deploymentType"]', loadAuthConfiguration);

  form.on('input', 'input[name="id"], input[name="url"]', () => {
    if (submitted) {
      validate();
    }
  });

  form.on('submit', event => {
    event.preventDefault();
    save();
  });

  // The form can't be closed while the instance is being saved (e.g. with the Escape key).
  modal.on('hide.bs.modal', event => {
    if (saving) {
      event.preventDefault();
    }
  });

  // Focus the first field once the modal is displayed.
  modal.on('shown.bs.modal', () => getField('id').trigger('focus'));
});

#jiraConfig .modal-title {
  font-weight: bold;
}

/* The fields take the whole width of the modal, whatever its size. */
#jiraInstanceModal .modal-body input[type="text"],
#jiraInstanceModal .modal-body input[type="password"],
#jiraInstanceModal .modal-body input[type="email"],
#jiraInstanceModal .modal-body select {
  width: 100%;
}

/* Only used to disable the fields while saving. */
#jiraInstanceModal fieldset.jira-instance-fields {
  border: 0;
  margin: 0;
  min-width: 0;
  padding: 0;
}

#jiraInstanceModal .jira-auth-configuration dl {
  margin: 0;
}

/* The Live Data breaks the values anywhere, even in the middle of the IDs and labels: keep the words whole, and only
   break the URLs anywhere, which are long and would widen the Live Data. */
#jiraInstances .livedata-displayer {
  overflow-wrap: break-word;
  word-break: normal;
}

#jiraInstances .jira-instance-url {
  overflow-wrap: anywhere;
}

#jiraInstances .jira-instance-actions {
  white-space: nowrap;
}

#jiraInstances .jira-instance-actions .action + .action {
  margin-left: .5em;
}

/* The invalid fields, once the form has been submitted. */
#jiraInstanceModal .has-error label {
  color: #a94442;
}

#jiraInstanceModal dd.has-error input {
  border-color: #a94442;
}
